<script setup lang="ts">
import {computed,ref,onMounted} from 'vue';import {useWorkbench} from '../stores/workbench';import {fmt,percent} from '../api/client';import StatusBadge from './StatusBadge.vue';import UiIcon from './UiIcon.vue';const s=useWorkbench(),feedback=ref('negotiate'),selected=ref<string[]>([]);const m=computed(()=>s.metrics||{}),before=computed(()=>m.value.before||{}),after=computed(()=>m.value.after||{}),n1=computed(()=>m.value.n1||before.value.n1||{});const risks:Record<string,string>={'低':'low','中':'medium','高':'high'};onMounted(()=>{if(!s.metrics)s.evaluate().catch(()=>{})});const cards=computed(()=>[{name:'最大线路负载率',before:percent(before.value.loading?.max),after:percent(after.value.loading?.max),detail:'平均 '+percent(before.value.loading?.mean)+' · 重载 '+(before.value.loading?.heavy_count??'—')+' 条 · 越限 '+(before.value.loading?.overload_count??'—')+' 条',icon:'chart'},{name:'最大电压偏移',before:fmt(before.value.voltage?.max,4)+' p.u.',after:after.value.voltage?fmt(after.value.voltage.max,4)+' p.u.':'—',detail:'平均 '+fmt(before.value.voltage?.mean,4)+' p.u. · '+(before.value.voltage?.violations??'—')+' 个母线越限',icon:'bolt'},{name:'N−1 直流筛查通过率',before:percent(n1.value.pass_rate),after:after.value.n1?percent(after.value.n1.pass_rate):'—',detail:(n1.value.passed??'—')+' / '+(n1.value.evaluated??'—')+' 个事故 · 非交流 N−1 校核',icon:'shield'}]);
</script><template><div class="content-pad"><div class="panel-heading"><div><div class="eyebrow">M7 / 任务书指标 4.2</div><h2>指标与风险评估</h2></div><span class="risk-context-pill">{{m.evaluation_stage==='post_result'?'基态与结果对比':'基态风险评估'}}</span><el-button :loading="s.busy" @click="s.evaluate().catch(()=>{})">重新评估</el-button></div><div v-if="!s.metrics" class="inline-empty large">正在根据真实断面计算指标与直流筛查…</div><template v-else><div class="notice"><UiIcon name="info"/><span>调整前指标来自真实断面。{{m.after?'调整后指标依据导入结果计算。':'当前没有可用的调整后结果，调整后显示“—”。'}}</span></div><div class="risk-metric-grid"><div v-for="card in cards" :key="card.name" class="metric-card"><div class="icon-label"><UiIcon :name="card.icon"/><span>{{card.name}}</span></div><div class="metric-values"><div><small>调整前</small><strong>{{card.before}}</strong></div><div><small>调整后</small><strong>{{card.after}}</strong></div></div><p>{{card.detail}}</p></div></div><div class="notice amber"><UiIcon name="shield"/><div><strong>直流近似筛查，非交流 N−1 校核</strong><p>使用 PTDF / LODF 与支路有功限额进行静态筛查。当前事故集按基础模型配置选取；孤岛事故单列，不计入 LODF 通过率。</p><p v-if="n1.islanding_count">孤岛事故：{{n1.islanding_count}} 条 · 涉及净负荷 {{fmt(n1.islanding_mw)}} MW</p></div></div><div class="two-columns"><div class="deferred-metric"><div><h3>静态电压稳定裕度</h3><p>需要连续潮流计算。</p></div><StatusBadge name="静态电压稳定裕度"/></div><div class="deferred-metric"><div><h3>新能源消纳率</h3><p>暂不计算：断面没有新能源机组信息。</p></div><StatusBadge name="新能源消纳率"/></div></div><section class="risk-assessment"><div class="section-heading"><h3>课题 3 风险评估</h3><StatusBadge name="课题 3 风险"/></div><div class="risk-heading"><div class="risk-level" :class="risks[m.risk?.risk_level]">{{m.risk?.risk_level||'—'}}<small>风险等级</small></div><div><strong>{{m.risk?.source||'本地规则模拟'}}</strong><p class="muted">{{/本地|模拟|local|mock/i.test(m.risk?.source||'本地')?'本地规则模拟，课题 3 接口预留；不构成交流安全认证。':'外部风险服务返回，详见评估依据。'}}</p><div v-if="m.risk?.basis" class="risk-basis"><span>评估依据</span><strong>{{typeof m.risk.basis==='string'?m.risk.basis:JSON.stringify(m.risk.basis)}}</strong></div><ul class="risk-reasons"><li v-for="(reason,i) in m.risk?.reasons||[]" :key="i">{{reason}}</li></ul></div></div></section><section class="spec-section"><div class="section-heading"><h3>反馈与动态调整</h3><el-radio-group v-model="feedback" size="small"><el-radio-button value="negotiate">协商调整</el-radio-button><el-radio-button value="reward">Reward</el-radio-button></el-radio-group></div><template v-if="feedback==='negotiate'"><p class="muted">勾选建议后生成新一版规格草稿。建议中的数值保持空白，由你在规格页填写并确认。</p><div v-for="sug in m.suggestions||[]" :key="sug.id" class="suggestion-card"><el-checkbox v-model="selected" :value="sug.id"><strong>{{sug.title}}</strong></el-checkbox><p>{{sug.reason}}</p><span class="inference-tag">数值待用户确认</span></div><div v-if="!m.suggestions?.length" class="inline-empty">当前规则没有产生调整建议。</div><div class="panel-bottom-actions"><span class="small-note">父版本 v{{s.spec.version}} → 新版本草稿</span><el-button type="primary" :disabled="!selected.length" :loading="s.busy" @click="s.adjust(selected).catch(()=>{})" data-testid="apply-adjustment">采纳建议并创建新版本 <UiIcon name="arrow" :size="15"/></el-button></div></template><div v-else class="soft-panel panel-pad"><h3>风险等级 → 奖励项 <StatusBadge name="Reward"/></h3><p>风险等级作为后续安全强化学习的反馈输入。奖励计算接口预留，当前不生成训练奖励。</p><div class="static-field">奖励项：{{m.risk?.reward??'—（待接入）'}}</div><details><summary>查看 Reward 接口契约</summary><pre class="json-block">{{JSON.stringify({request:s.integrations.find(i=>i.id==='risk')?.request,response:s.integrations.find(i=>i.id==='risk')?.response},null,2)}}</pre></details></div></section><details><summary>查看计算口径与可用性</summary><pre class="json-block">{{JSON.stringify({basis:m.basis,availability:m.availability,n1:{method:n1.method,evaluated:n1.evaluated,islanding_count:n1.islanding_count} },null,2)}}</pre></details></template></div></template>